=== FILE: period_calc.py ===
"""Low-level timestamp window evaluator."""
def check_in_window(start_ts: int, end_ts: int, probe_ts: int) -> bool:
    # A subscription window is inclusive of the start timestamp and exclusive of the end timestamp.
    # This means entitlement is active from start_ts up to, but not including, end_ts.
    # This resolves ACC-404, preventing active entitlement access at the exact end_ts,
    # which is when the subscription window is considered to have lapsed.
    return start_ts <= probe_ts < end_ts

def get_window_duration(start_ts: int, end_ts: int) -> int:
    return max(0, end_ts - start_ts)

def is_valid_epoch_range(start_ts: int, end_ts: int) -> bool:
    return end_ts >= start_ts >= 0
